    [6907]={name="Tortoise Armor",quality=3,ilvl=27,reqLevel=22,sourceType="boss_drop",instructions="Drops from Ghamoo-ra.",zone="Blackfathom Deeps",npc="Ghamoo-ra"},
    [6908]={name="Ghamoo-ra's Bind",quality=3,ilvl=27,reqLevel=22,sourceType="boss_drop",instructions="Drops from Ghamoo-ra.",zone="Blackfathom Deeps",npc="Ghamoo-ra",lore="Ghamoo-ra is the ancient turtle the naga keep in Blackfathom Deeps -- old enough that the Twilight cultists there treat it as part of the temple."},
    [6909]={name="Strike of the Hydra",quality=3,ilvl=31,reqLevel=26,sourceType="boss_drop",instructions="Drops from Aku'mai.",zone="Blackfathom Deeps",npc="Aku'mai",proc="Chance on hit: Inflict 42 Fire and 14 Frost damage, slow the target by 50% for 5 sec, reduce armor by 50, and inflict 7 Nature damage every 3 sec for 12 sec."},
