    [11809]={name="Flame Wrath",quality=3,ilvl=56,reqLevel=51,sourceType="boss_drop",instructions="Drops from Ambassador Flamelash.",zone="Blackrock Depths",npc="Ambassador Flamelash",lore="Ragnaros's envoy to the Dark Iron in Blackrock Depths, sent to keep the dwarves loyal to the Firelord.",proc="Chance on hit: Shoots a ring of fire dealing 133 to 175 Fire damage to all nearby enemies, and envelops the caster with a Fire Shield for 15 sec."},
