    [16039]={name="Ta'Kierthan Songblade",quality=3,ilvl=59,reqLevel=54,sourceType="rare_npc",instructions="Drops from Lord Darkscythe.",zone="Eastern Plaguelands",npc="Lord Darkscythe"},
    [16058]={name="Fordring's Seal",quality=3,ilvl=63,reqLevel=52,sourceType="quest_reward",instructions="Reward from the quest 'In Dreams'. Pick it over the other reward choices. Starts with Tirion Fordring in Eastern Plaguelands. Objective: Escort Taelan Fordring out of Hearthglen.",zone="Eastern Plaguelands",questName="In Dreams",lore="For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become?"},
    [16309]={name="Drakefire Amulet",quality=3,ilvl=63,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Drakefire Amulet'. The chain starts with Haleh in Winterspring. Retrieve the Blood of the Black Dragon Champion from General Drakkisath in Blackrock Spire. That step is level 60.",zone="Blackrock Spire",questName="Drakefire Amulet",lore="It is a piece of the dragon; a scale - enchanted and transformed. Whole, it could have granted access to the beast's lair. Shattered, it is useless."},
